#include <bits/stdc++.h>
using namespace std;

int maxMeetings(vector<int>& start, vector<int>& end) {
    int n = start.size();
    vector<pair<int, int>> meetings;  // {end, start}
    for (int i = 0; i < n; ++i) meetings.push_back({end[i], start[i]});
    sort(meetings.begin(), meetings.end());
    int count = 0, lastEnd = -1;
    for (auto& [finish, begin] : meetings) {
        if (begin > lastEnd) {
            ++count;
            lastEnd = finish;
        }
    }
    return count;
}

