import java.util.*;

class Solution {
    public int maxMeetings(int[] start, int[] end) {
        int n = start.length;
        int[][] meetings = new int[n][2];
        for (int i = 0; i < n; ++i) { meetings[i][0] = end[i]; meetings[i][1] = start[i]; }
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);
        int count = 0, lastEnd = -1;
        for (int[] m : meetings) {
            if (m[1] > lastEnd) {
                ++count;
                lastEnd = m[0];
            }
        }
        return count;
    }
}
